        )}
      </div>
      {editing && <CollectionModal kind="folder" initial={d} onClose={() => setEditing(false)} onSaved={() => { setEditing(false); f.reload() }} />}
      {folderFor && <AddToFolderModal meeting={folderFor} onClose={() => setFolderFor(null)} />}
